    INSERT INTO mcqs (topic_id, question, options, correct_index, explanation) VALUES
    (v_topic_id, '1: What is the most accurate method for determining the gestational age of a pregnancy in the first trimester?', '["Last Menstrual Period (LMP)", "Crown-Rump Length (CRL) on Ultrasound", "Biparietal Diameter (BPD)", "Fundal height measurement"]', 1, 'First-trimester ultrasound (CRL) is the most accurate method, with a margin of error of +/- 3-5 days. (ACOG)'),
    (v_topic_id, '2: According to Naegele''s rule, if a woman''s LMP was January 1st, what is her estimated date of delivery (EDD)?', '["October 1st", "October 8th", "September 24th", "November 1st"]', 1, 'Naegele''s Rule: LMP + 7 days - 3 months + 1 year. Jan 1 + 7 days = Jan 8. Jan 8 - 3 months = Oct 8. (Williams)'),
    (v_topic_id, '3: Which of the following cardiovascular changes is considered normal during pregnancy?', '["Decreased cardiac output", "Increased systemic vascular resistance", "Increased plasma volume by 40-50%", "Decreased heart rate"]', 2, 'Plasma volume increases significantly, leading to the "physiologic anemia of pregnancy" due to hemodilution. (Beckmann)'),
    (v_topic_id, '4: At how many weeks gestation should the fundus typically be felt at the level of the umbilicus?', '["12 weeks", "16 weeks", "20 weeks", "24 weeks"]', 2, 'At 20 weeks, the fundus is at the umbilicus. Before that, it is midway between symphysis and umbilicus at 16 weeks. (Gabbe)'),
    (v_topic_id, '5: What is the recommended daily intake of folic acid for a low-risk woman planning pregnancy to prevent neural tube defects?', '["40 mcg", "400 mcg (0.4 mg)", "4 mg", "10 mg"]', 1, '400 mcg daily for low-risk women; 4 mg for high-risk (previous child with NTD). (ACOG)'),
    (v_topic_id, '6: Which of the following is a classic skin change in pregnancy characterized by hyperpigmentation of the face?', '["Linea nigra", "Striae gravidarum", "Chloasma (Melasma)", "Spider angiomata"]', 2, 'Chloasma is the "mask of pregnancy," caused by increased melanocyte-stimulating hormone. (Williams)'),
    (v_topic_id, '7: A "Chadwick sign" on physical exam refers to:', '["Softening of the cervix", "Bluish discoloration of the cervix and vagina", "Softening of the lower uterine segment", "Fetal movement felt by the examiner"]', 1, 'Chadwick sign is due to increased pelvic vascularity and is a presumptive sign of pregnancy. (Beckmann)'),
    (v_topic_id, '8: Which hormone is primarily responsible for maintaining the corpus luteum in early pregnancy until the placenta takes over?', '["Estrogen", "Progesterone", "Human Chorionic Gonadotropin (hCG)", "Human Placental Lactogen (hPL)"]', 2, 'hCG, produced by the syncytiotrophoblast, mimics LH to maintain the corpus luteum. (Gabbe)'),
    (v_topic_id, '9: At approximately how many weeks gestation does the placenta typically take over progesterone production from the corpus luteum?', '["4 weeks", "8-10 weeks", "16 weeks", "20 weeks"]', 1, 'The luteal-placental shift occurs around 8-10 weeks. (Williams)'),
    (v_topic_id, '10: Which of the following laboratory tests is routinely performed at the first prenatal visit?', '["Glucose Challenge Test (GCT)", "Group B Strep (GBS) culture", "Blood type, Rh factor, and antibody screen", "Fetal fibronectin"]', 2, 'Initial labs include blood type/Rh, CBC, Rubella immunity, HBsAg, RPR/VDRL, HIV, and Urinalysis. (ACOG)'),
    (v_topic_id, '11: A woman with Rh-negative blood type should receive Rho(D) immune globulin (RhoGAM) routinely at how many weeks gestation if she is unsensitized?', '["12 weeks", "20 weeks", "28 weeks", "At delivery only"]', 2, 'RhoGAM is given at 28 weeks and within 72 hours of delivery if the neonate is Rh-positive. (Williams)'),
    (v_topic_id, '12: What is the purpose of the "Combined Screen" (nuchal translucency + serum PAPP-A/hCG) performed between 11-14 weeks?', '["Screening for neural tube defects", "Screening for Trisomy 21 and 18", "Diagnosing gestational diabetes", "Assessing cervical length"]', 1, 'The first-trimester screen assesses the risk for aneuploidy. (Gabbe)'),
    (v_topic_id, '13: Screening for Gestational Diabetes Mellitus (GDM) using the 50g 1-hour glucose challenge test is routinely performed at:', '["12-16 weeks", "20-22 weeks", "24-28 weeks", "32-34 weeks"]', 2, 'Universal screening occurs late in the second trimester when insulin resistance increases due to placental hormones (hPL). (ACOG)'),
    (v_topic_id, '14: A Group B Streptococcus (GBS) rectovaginal culture is routinely performed at how many weeks?', '["20-24 weeks", "28-30 weeks", "36-37 weeks", "Only during labor"]', 2, 'Screening is done late to ensure the status is current for delivery. (Williams)'),
    (v_topic_id, '15: Which of the following vaccines is specifically recommended during every pregnancy, ideally between 27-36 weeks?', '["MMR", "Varicella", "Tdap (Tetanus, Diphtheria, Pertussis)", "HPV"]', 2, 'Tdap is given to provide passive immunity to the neonate against pertussis (whooping cough). (ACOG)'),
    (v_topic_id, '16: Which of the following is a "positive" sign of pregnancy (diagnostic, not just presumptive or probable)?', '["Amenorrhea", "Positive urine pregnancy test", "Detection of fetal heart tones by Doppler", "Quickening"]', 2, 'Positive signs include fetal heart tones, fetal movement felt by examiner, and visualization of fetus on ultrasound. (Beckmann)'),
    (v_topic_id, '17: What is the normal range for a fetal heart rate?', '["80-100 bpm", "110-160 bpm", "140-180 bpm", "60-120 bpm"]', 1, '110-160 bpm is the standard baseline fetal heart rate. (ACOG)'),
    (v_topic_id, '18: Which hormone is responsible for the relaxation of the pelvic ligaments and softening of the cervix in preparation for labor?', '["Oxytocin", "Prolactin", "Relaxin", "Thyroxine"]', 2, 'Relaxin (and progesterone) increases joint laxity in pregnancy. (Gabbe)'),
    (v_topic_id, '19: "Quickening" (the first perception of fetal movement) typically occurs at what gestational age?', '["8-10 weeks", "12-14 weeks", "18-20 weeks (earlier in multiparas)", "24-26 weeks"]', 2, 'Primigravidas usually feel it around 20 weeks; multiparas around 16-18 weeks. (Williams)'),
    (v_topic_id, '20: What is the recommended weight gain during pregnancy for a woman with a normal pre-pregnancy BMI (18.5-24.9)?', '["11-20 lbs", "25-35 lbs", "15-25 lbs", "No more than 10 lbs"]', 1, 'IOM guidelines recommend 25-35 lbs (11-16 kg) for normal BMI. (IOM)'),
    (v_topic_id, '21: Which position is most likely to cause "Supine Hypotensive Syndrome" in late pregnancy?', '["Left lateral decubitus", "Right lateral decubitus", "Supine (lying on back)", "Semi-Fowler''s"]', 2, 'The heavy uterus compresses the Inferior Vena Cava (IVC), decreasing venous return and cardiac output. (Beckmann)'),
    (v_topic_id, '22: "Physiologic Anemia of Pregnancy" is primarily due to:', '["Iron deficiency", "Vitamin B12 deficiency", "A greater increase in plasma volume compared to red blood cell mass", "Acute blood loss"]', 2, 'Plasma volume increases ~50% while RBC mass increases ~20%, causing a drop in hematocrit. (Gabbe)'),
    (v_topic_id, '23: Which of the following renal changes is normal during pregnancy?', '["Decreased Glomerular Filtration Rate (GFR)", "Increased serum creatinine", "Dilation of the renal pelvis and ureters (right > left)", "Decreased renal blood flow"]', 2, 'Physiologic hydronephrosis/hydroureter is due to progesterone-mediated relaxation and mechanical compression. (Williams)'),
    (v_topic_id, '24: A pregnant woman at 10 weeks gestation has a TSH of 0.2 mIU/L (low) and a slightly elevated free T4. She is asymptomatic. What is the most likely cause?', '["Graves disease", "Subacute thyroiditis", "Normal physiologic effect of hCG", "Iodine deficiency"]', 2, 'The alpha-subunit of hCG is identical to TSH, allowing it to weakly stimulate the thyroid, suppressing TSH in the first trimester. (Gabbe)'),
    (v_topic_id, '25: Which of the following is the most common cause of a first-trimester spontaneous abortion?', '["Maternal trauma", "Uterine anomalies", "Fetal chromosomal abnormalities (aneuploidy)", "Maternal infection"]', 2, 'Aneuploidy (mostly trisomies) accounts for ~50% of early miscarriages. (Williams)'),
    (v_topic_id, '26: Which imaging modality is first-line for evaluating an adnexal mass in a pregnant woman?', '["CT scan", "MRI", "Pelvic Ultrasound", "X-ray Pelvis"]', 2, 'Ultrasound is safe, effective, and avoids ionizing radiation. (ACOG)'),
    (v_topic_id, '27: What is the significance of a "Positive Nitrazine Test" in a pregnant woman presenting with leaking fluid?', '["Indicates bacterial vaginosis", "Suggests Rupture of Membranes (ROM)", "Confirms yeast infection", "Normal finding"]', 1, 'Amniotic fluid is alkaline (pH > 7.0), which turns the yellow nitrazine paper blue. (Beckmann)'),
    (v_topic_id, '28: What is the classic "ferning" pattern seen on a slide of dried vaginal fluid indicative of?', '["Cervical mucus during ovulation", "Amniotic fluid (confirming ROM)", "Semen", "Bacterial infection"]', 1, 'Crystallization of salts in amniotic fluid creates the fern pattern. (Gabbe)'),
    (v_topic_id, '29: An "Anatomy Scan" ultrasound is typically performed at how many weeks?', '["12 weeks", "16 weeks", "18-22 weeks", "32 weeks"]', 2, 'This is the optimal window to visualize fetal structures and organs. (ACOG)'),
    (v_topic_id, '30: Which of the following is an absolute contraindication to exercise in pregnancy?', '["Advanced maternal age", "Obesity", "Preterm Rupture of Membranes (PROM)", "Gestational diabetes"]', 2, 'PROM, cerclage, and restrictive lung disease are contraindications. (ACOG)'),
    (v_topic_id, '31: A woman is "G3P1011." This indicates:', '["3 pregnancies, 1 term birth, 0 preterm, 1 abortion, 1 living child", "3 pregnancies, 1 birth, 11 total children", "3 pregnancies, 1 twin birth", "None of the above"]', 0, 'G (Gravida), P (Para: Term, Preterm, Abortus, Living). (Beckmann)'),
    (v_topic_id, '32: What is the minimum recommended interval between the end of one pregnancy and the beginning of the next (interpregnancy interval) for optimal outcomes?', '["6 months", "18 months", "3 years", "5 years"]', 1, 'Intervals < 18 months are associated with increased risks of preterm birth and SGA. (WHO/ACOG)'),
    (v_topic_id, '33: Which of the following should be avoided by a pregnant woman to prevent Toxoplasmosis?', '["Undercooked meat and cat feces", "Soft cheeses and deli meats", "Raw fish (Sushi)", "Unwashed vegetables"]', 0, 'Toxoplasma gondii is found in cat litter and undercooked meat. (Williams)'),
    (v_topic_id, '34: "Listeria monocytogenes" infection in pregnancy is most commonly associated with the consumption of:', '["Raw eggs", "Unpasteurized dairy and deli meats", "Canned foods", "Fresh fruit"]', 1, 'Listeria can cross the placenta and cause fetal death or neonatal sepsis. (Gabbe)'),
    (v_topic_id, '35: What is the primary concern with Mercury exposure in pregnancy?', '["Skeletal deformities", "Neurotoxicity and developmental delay", "Heart defects", "Renal failure"]', 1, 'Mercury (often from high-predatory fish) affects fetal brain development. (EPA/ACOG)'),
    (v_topic_id, '36: Which of the following medications is a known teratogen and should be avoided in pregnancy?', '["Acetaminophen", "Isotretinoin (Accutane)", "Penicillin", "Insulin"]', 1, 'Isotretinoin causes severe CNS, craniofacial, and cardiac defects. (Beckmann)'),
    (v_topic_id, '37: ACE inhibitors (e.g., Lisinopril) are avoided in pregnancy primarily because they cause:', '["Limb defects", "Fetal renal anomalies and oligohydramnios", "Neural tube defects", "Cleft palate"]', 1, 'They interfere with fetal renal development in the 2nd and 3rd trimesters. (Williams)'),
    (v_topic_id, '38: Warfarin is a teratogen that causes:', '["Fetal warfarin syndrome (nasal hypoplasia, stippled epiphyses)", "Ebstein anomaly", "Gray baby syndrome", "Clear cell adenocarcinoma"]', 0, 'Warfarin is avoided; Heparin or LMWH is used for anticoagulation. (Gabbe)'),
    (v_topic_id, '39: Which antibiotic is avoided in pregnancy because it causes "discoloration of the teeth" and affects bone growth?', '["Amoxicillin", "Tetracycline", "Ceftriaxone", "Azithromycin"]', 1, 'Tetracyclines (and Doxycycline) deposit in calcifying tissues. (Beckmann)'),
    (v_topic_id, '40: What is the most common cause of "post-term" pregnancy (>= 42 weeks)?', '["Maternal age", "Inaccurate dating (incorrect LMP)", "Fetal macrosomia", "Placental insufficiency"]', 1, 'Uncertainty about the date of ovulation/LMP is the #1 reason. (Williams)'),
    (v_topic_id, '41: A "Biophysical Profile" (BPP) score of 4/10 indicates:', '["Reassuring fetal status", "Equivocal, repeat in 24 hours", "Abnormal, suggestive of fetal hypoxia", "Normal for 32 weeks"]', 2, 'BPP scores <= 4 generally indicate a need for delivery or intensive evaluation. (ACOG)'),
    (v_topic_id, '42: What are the five components of a Biophysical Profile?', '["Fetal HR, Tone, Movement, Breathing, Amniotic Fluid Volume", "Fetal HR, Weight, Tone, Breathing, Position", "Amniotic Fluid, Doppler, Tone, Movement, HR", "None of the above"]', 0, 'Each component is worth 2 points. (Gabbe)'),
    (v_topic_id, '43: A "Reactive" Non-Stress Test (NST) is defined by:', '["At least 2 accelerations of 15 bpm for 15 seconds in 20 minutes", "No decelerations", "Stable baseline heart rate", "Presence of contractions"]', 0, 'Accelerations indicate fetal well-being and an intact nervous system. (ACOG)'),
    (v_topic_id, '44: Which fetal screening test measures free fetal DNA in maternal blood?', '["Quad screen", "Cell-free DNA (cfDNA) screening / NIPT", "Amniocentesis", "CVS"]', 1, 'NIPT is highly sensitive for Trisomy 21, 18, and 13 after 10 weeks. (Williams)'),
    (v_topic_id, '45: Chorionic Villus Sampling (CVS) is typically performed at:', '["8-10 weeks", "10-13 weeks", "15-20 weeks", "Anytime after 24 weeks"]', 1, 'CVS allows for earlier genetic diagnosis than amniocentesis. (Beckmann)'),
    (v_topic_id, '46: Amniocentesis is typically performed at how many weeks?', '["10-12 weeks", "15-20 weeks", "24-28 weeks", "36-40 weeks"]', 1, 'Performed once there is adequate amniotic fluid and the membranes have fused. (Williams)'),
    (v_topic_id, '47: What is the primary risk associated with invasive testing (CVS/Amnio)?', '["Fetal malformation", "Pregnancy loss (miscarriage)", "Maternal infection", "Premature labor"]', 1, 'The risk is low (~0.1-0.5%) but present. (ACOG)'),
    (v_topic_id, '48: Which serum marker is elevated in a "Quad Screen" if there is an open neural tube defect?', '["hCG", "Estriol", "Inhibin-A", "Alpha-fetoprotein (AFP)"]', 3, 'AFP escapes into the amniotic fluid and maternal serum through the opening. (Gabbe)'),
    (v_topic_id, '49: What is the most common cause of an "elevated AFP" on a screening test?', '["Neural tube defect", "Multiple gestation (twins)", "Under-estimation of gestational age (dating error)", "Abdominal wall defect"]', 2, 'Incorrect dating is the most common reason for abnormal quad screen results. (Beckmann)'),
    (v_topic_id, '50: A "low AFP," "low estriol," and "high hCG/Inhibin-A" on a Quad screen is suggestive of:', '["Trisomy 18", "Trisomy 21 (Down Syndrome)", "Neural tube defect", "Normal pregnancy"]', 1, 'Classic "High-High, Low-Low" pattern for Down Syndrome. (Williams)'),
    (v_topic_id, '51: Which of the following is the most appropriate management for a woman with "morning sickness" (Nausea/Vomiting of Pregnancy)?', '["Ondansetron (Zofran) as first-line", "Pyridoxine (Vitamin B6) and Doxylamine", "Strict NPO", "IV fluids only"]', 1, 'B6 + Doxylamine is the first-line pharmacotherapy recommended by ACOG. (ACOG)'),
    (v_topic_id, '52: What defines "Hyperemesis Gravidarum"?', '["Nausea every morning", "Severe NVP with weight loss (>5%) and ketonuria", "Heartburn", "Vomiting once a day"]', 1, 'Severe form requiring hydration and sometimes hospitalization. (Beckmann)'),
    (v_topic_id, '53: Heartburn (GERD) is common in pregnancy due to:', '["Increased acid production", "Progesterone-mediated relaxation of the Lower Esophageal Sphincter", "Fetal kicks to the stomach", "Eating too much"]', 1, 'Smooth muscle relaxation affects the LES. (Gabbe)'),
    (v_topic_id, '54: Constipation in pregnancy is primarily due to:', '["Decreased water intake", "Increased physical activity", "Progesterone-mediated decrease in gut motility", "Pressure from the fetus"]', 2, 'Progesterone slows transit time, allowing for more water absorption. (Williams)'),
    (v_topic_id, '55: "Ptyalism" in pregnancy refers to:', '["Excessive salivation", "Excessive sweating", "Nasal congestion", "Leg cramps"]', 0, 'Often associated with severe nausea. (Beckmann)'),
    (v_topic_id, '56: Why are pregnant women at increased risk for Pyelonephritis if they have asymptomatic bacteriuria?', '["They are immunosuppressed", "Progesterone-mediated ureteral dilation and vesicoureteral reflux", "They don''t drink enough water", "High estrogen levels"]', 1, 'Stasis of urine in the dilated ureters allows bacteria to ascend to the kidneys. (ACOG)'),
    (v_topic_id, '57: Which of the following antibiotics is first-line for asymptomatic bacteriuria in pregnancy?', '["Ciprofloxacin", "Nitrofurantoin or Cephalexin", "Doxycycline", "Tetracycline"]', 1, 'Quinolones and Tetracyclines are generally avoided. (Williams)'),
    (v_topic_id, '58: What is the significance of "painless vaginal bleeding" in the third trimester?', '["Abruptio placentae", "Placenta previa", "Normal bloody show", "Uterine rupture"]', 1, 'Previa is painless; Abruption is usually painful. (Gabbe)'),
    (v_topic_id, '59: Why is a digital pelvic exam contraindicated in a woman with 3rd-trimester vaginal bleeding until previa is ruled out?', '["It causes infection", "It can trigger labor", "It can cause massive hemorrhage if the placenta is over the cervix", "It is uncomfortable"]', 2, 'Speculum and US first. Never stick a finger in a bleeding 3rd-trimester patient without knowing where the placenta is! (ACOG)'),
    (v_topic_id, '60: Which of the following is a symptom of "Pre-eclampsia" that a woman should be warned about?', '["Severe headache or visual changes", "Increased fetal movement", "Hunger", "Leg cramps"]', 0, 'Warning signs of severe features include RUQ pain, headache, and blurred vision. (Beckmann)'),
    (v_topic_id, '61: In the first trimester, how often should hCG levels ideally increase in a normal intrauterine pregnancy?', '["Triple every 24 hours", "Double every 48 hours", "Increase by 10% weekly", "Stay the same"]', 1, 'A rise of at least 35-53% in 48 hours is expected in early viable IUPs. (ACOG)'),
    (v_topic_id, '62: What is the "Discriminatory Zone" for hCG on transvaginal ultrasound?', '["500 mIU/mL", "1500-2000 mIU/mL", "5000 mIU/mL", "10,000 mIU/mL"]', 1, 'The level above which an intrauterine gestational sac should be visible. (Williams)'),
    (v_topic_id, '63: Which of the following is the most common site for an ectopic pregnancy?', '["Ovary", "Cervix", "Fallopian tube (ampulla)", "Abdominal cavity"]', 2, 'The ampulla of the fallopian tube is the #1 site. (Gabbe)'),
    (v_topic_id, '64: What is the pharmacological treatment for a small, unruptured ectopic pregnancy in a stable patient?', '["Progesterone", "Methotrexate", "Misoprostol", "Lisinopril"]', 1, 'Methotrexate is a folic acid antagonist that stops trophoblast growth. (ACOG)'),
    (v_topic_id, '65: A woman presents with "grape-like" vesicles passed per vagina and a snowstorm pattern on ultrasound. Diagnosis?', '["Twin pregnancy", "Ectopic pregnancy", "Hydatidiform mole (Gestational Trophoblastic Disease)", "Placental abruption"]', 2, 'Moles are characterized by excessive trophoblastic proliferation. (Beckmann)'),
    (v_topic_id, '66: Which type of molar pregnancy has a 46,XX karyotype with DNA entirely from the father?', '["Complete mole", "Partial mole", "Choriocarcinoma", "Normal IUP"]', 0, 'Empty egg fertilized by one sperm that duplicates its DNA. (Williams)'),
    (v_topic_id, '67: What is the classic finding for a "Partial Mole" karyotype?', '["46,XX", "46,XY", "69,XXY (Triploidy)", "45,X"]', 2, 'Egg fertilized by two sperm. (Gabbe)'),
    (v_topic_id, '68: What is the most important follow-up for a patient after evacuation of a molar pregnancy?', '["Serial Ultrasounds", "Serial hCG levels to screen for persistent disease/choriocarcinoma", "Chest X-ray", "Liver function tests"]', 1, 'Monitoring hCG until it reaches zero and stays there for months. (ACOG)'),
    (v_topic_id, '69: Which hormone is responsible for "linea nigra" and "darkening of the areola"?', '["Estrogen", "Progesterone", "Melanocyte Stimulating Hormone (MSH)", "hPL"]', 2, 'Stimulated by high estrogen/progesterone levels. (Beckmann)'),
    (v_topic_id, '70: "Braxton-Hicks" contractions are:', '["Early labor contractions", "Irregular, painless "false labor" contractions", "Contractions during the third stage of labor", "Normal fetal movements"]', 1, 'They do not cause cervical change. (Williams)'),
    (v_topic_id, '71: What is the primary source of amniotic fluid in the second and third trimesters?', '["Maternal plasma", "Fetal urine", "Fetal sweat", "Placental secretions"]', 1, 'Fetal swallowing and urination regulate the fluid volume. (Gabbe)'),
    (v_topic_id, '72: "Oligohydramnios" (too little fluid) is often associated with:', '["Fetal esophageal atresia", "Fetal renal agenesis (Potter sequence)", "Maternal diabetes", "Multiple gestation"]', 1, 'If the fetus can''t urinate, there is no fluid. (Beckmann)'),
    (v_topic_id, '73: "Polyhydramnios" (too much fluid) is often associated with:', '["Fetal swallowing defects (e.g., Duodenal atresia)", "Renal agenesis", "Rupture of membranes", "IUGR"]', 0, 'If the fetus can''t swallow, fluid builds up. (Williams)'),
    (v_topic_id, '74: What is the "Amniotic Fluid Index" (AFI) threshold for oligohydramnios?', '["< 2 cm", "< 5 cm", "< 10 cm", "< 20 cm"]', 1, 'AFI < 5 cm or deepest vertical pocket < 2 cm. (ACOG)'),
    (v_topic_id, '75: Maternal "Physiologic Hydronephrosis" is more common on the right side because:', '["The right kidney is larger", "The right ureter is compressed by the dextrorotated uterus and iliac vessels", "Gravity", "None of the above"]', 1, 'The uterus usually rotates to the right in pregnancy. (Gabbe)'),
    (v_topic_id, '76: Which of the following is a normal respiratory change in pregnancy?', '["Decreased respiratory rate", "Increased Tidal Volume and Minute Ventilation", "Increased Functional Residual Capacity (FRC)", "Metabolic acidosis"]', 1, 'Pregnancy is a state of compensated respiratory alkalosis (lower pCO2) to facilitate CO2 transfer from fetus. (Williams)'),
    (v_topic_id, '77: "Epulis gravidarum" is a:', '["Vaginal lesion", "Benign vascular tumor of the gums", "Skin rash", "Headache type"]', 1, 'Common oral finding due to high estrogen. (Beckmann)'),
    (v_topic_id, '78: What is the most common cause of neonatal mortality and morbidity?', '["Congenital anomalies", "Infection", "Preterm birth", "Birth trauma"]', 2, 'Prevention of preterm birth is a major goal of prenatal care. (Williams)'),
    (v_topic_id, '79: Which of the following is a risk factor for "Ectopic Pregnancy"?', '["Previous ectopic", "History of PID", "Smoking", "All of the above"]', 3, 'Anything that slows tubular transport. (Gabbe)'),
    (v_topic_id, '80: A "Snowstorm" appearance on ultrasound is pathognomonic for:', '["Molar pregnancy", "Twins", "Placental abruption", "Uterine fibroids"]', 0, 'Multiple small hydropic villi. (Beckmann)'),
    (v_topic_id, '81: How is the "Length of Pregnancy" calculated from the first day of the LMP?', '["266 days (38 weeks)", "280 days (40 weeks)", "300 days", "9 months exactly"]', 1, 'Gestation is 40 weeks from LMP; 38 weeks from fertilization. (Williams)'),
    (v_topic_id, '82: What is the frequency of prenatal visits for a low-risk woman before 28 weeks?', '["Every week", "Every 2 weeks", "Every 4 weeks", "Once a trimester"]', 2, 'Monthly until 28 weeks, then every 2 weeks until 36 weeks, then weekly. (ACOG)'),
    (v_topic_id, '83: Which mineral requirement increases significantly in pregnancy to support fetal growth and maternal blood volume?', '["Calcium", "Iron", "Zinc", "Magnesium"]', 1, '27 mg of elemental iron daily is recommended. (ACOG)'),
    (v_topic_id, '84: What is the most common reason for a "falsely elevated" AFP level?', '["Neural tube defect", "Multiple gestation", "Under-estimation of gestational age", "Omphalocele"]', 2, 'Always re-check dating with ultrasound first. (Gabbe)'),
    (v_topic_id, '85: A woman at 32 weeks gestation has a hemoglobin of 10.5 g/dL. This is considered:', '["Severe anemia", "Normal for the third trimester (physiologic hemodilution)", "Internal bleeding", "Lead poisoning"]', 1, 'Hgb > 11 in 1st/3rd trimester and > 10.5 in 2nd is normal. (CDC/ACOG)'),
    (v_topic_id, '86: Which of the following hormones is the basis for the home pregnancy test?', '["Progesterone", "Estriol", "beta-hCG", "LH"]', 2, 'hCG is unique to pregnancy and detectable in urine. (Beckmann)'),
    (v_topic_id, '87: "Morning sickness" typically peaks around how many weeks?', '["4 weeks", "8-12 weeks", "20 weeks", "Delivery"]', 1, 'Corresponds with peak hCG levels. (Williams)'),
    (v_topic_id, '88: Which physical finding is a probable (not positive) sign of pregnancy?', '["Hegar''s sign (softening of lower uterine segment)", "Ballottement", "Positive pregnancy test", "All of the above"]', 3, 'Probable signs are mostly objective but could have other causes. (Beckmann)'),
    (v_topic_id, '89: "Spider angiomata" and "palmar erythema" in pregnancy are due to:', '["High estrogen levels", "High blood pressure", "Vitamin deficiency", "Poor circulation"]', 0, 'Estrogen causes skin vascular changes. (Gabbe)'),
    (v_topic_id, '90: Why is a "pelvic exam" performed at the first prenatal visit?', '["To screen for STIs and check cervical/uterine size", "To check for labor", "To measure the baby''s head", "None of the above"]', 0, 'Includes Pap smear, cultures, and bimanual exam. (Williams)'),
    (v_topic_id, '91: At 12 weeks gestation, where is the uterus typically palpable?', '["Not palpable yet", "At the symphysis pubis", "Midway between symphysis and umbilicus", "At the umbilicus"]', 1, 'It just rises out of the pelvis at 12 weeks. (Beckmann)'),
    (v_topic_id, '92: Which infectious screen is routinely repeated in the third trimester for high-risk patients?', '["HIV, Syphilis, and Gonorrhea/Chlamydia", "Rubella", "Varicella", "Toxoplasmosis"]', 0, 'To prevent vertical transmission. (ACOG)'),
    (v_topic_id, '93: "Fetal Fibronectin" (fFN) is a test used to:', '["Screen for Down syndrome", "Assess the risk of preterm delivery in the next 1-2 weeks", "Confirm ROM", "Measure fetal weight"]', 1, 'A negative test has a high negative predictive value for preterm birth. (Gabbe)'),
    (v_topic_id, '94: Which of the following is a risk factor for developing Pre-eclampsia?', '["Nulliparity", "Chronic hypertension", "Obesity", "All of the above"]', 3, 'Multifactorial risk. (ACOG)'),
    (v_topic_id, '95: In a twin pregnancy, what is the most important factor determining the risk of complications?', '["Maternal age", "Chorionicity (number of placentas)", "Birth weight", "Fetal sex"]', 1, 'Monochorionic twins have much higher risks (e.g., TTTS). (Williams)'),
    (v_topic_id, '96: "Monoamniotic-monochorionic" (MoMo) twins carry a high risk of:', '["Cleft palate", "Umbilical cord entanglement", "Twin-to-twin transfusion", "Down syndrome"]', 1, 'Because they share one sac. (Gabbe)'),
    (v_topic_id, '97: Which maternal infection is associated with "snuffles" and "palmar rash" in the neonate?', '["HIV", "Syphilis", "Hepatitis B", "CMV"]', 1, 'Congenital syphilis. (Beckmann)'),
    (v_topic_id, '98: A "Symphysis-Fundal Height" (SFH) of 24 cm at 24 weeks gestation is:', '["Abnormal (too big)", "Normal (matches gestational age +/- 2 cm)", "Abnormal (too small)", "Indicative of twins"]', 1, 'The rule of thumb between 20-36 weeks. (Gabbe)'),
    (v_topic_id, '99: Which positions of the fetus are considered "malpresentations"?', '["Breech (feet first)", "Transverse lie (sideways)", "Face or brow presentation", "All of the above"]', 3, 'Cephalic (vertex) is the only normal presentation. (Williams)'),
    (v_topic_id, '100: "Pruritic Urticarial Papules and Plaques of Pregnancy" (PUPPP) typically appears in:', '["First trimester", "Second trimester", "Third trimester", "Postpartum"]', 2, 'Common in primigravidas, usually starts in the striae. (Beckmann)');
